#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int type; // 0 = leaf, 1 = internal with left/right
    struct Node *left;
    struct Node *right;
} Node;

Node* parse_tree(const char **s) {
    // skip spaces
    while (**s == ' ') (*s)++;
    if (**s == '\0') return NULL;
    if (**s == '(' && *(*s+1) == ')') {
        // leaf node
        *s += 2;
        Node* n = (Node*)malloc(sizeof(Node));
        n->type = 0;
        n->left = n->right = NULL;
        return n;
    }
    // internal node: ( left right )
    if (**s == '(') {
        (*s)++; // skip '('
        Node* left = parse_tree(s);
        // skip space between left and right
        while (**s == ' ') (*s)++;
        Node* right = parse_tree(s);
        // skip ')'
        if (**s == ')') (*s)++;
        Node* n = (Node*)malloc(sizeof(Node));
        n->type = 1;
        n->left = left;
        n->right = right;
        return n;
    }
    return NULL;
}

void free_tree(Node* root) {
    if (!root) return;
    if (root->type == 1) {
        free_tree(root->left);
        free_tree(root->right);
    }
    free(root);
}

Node* intersect(Node* t1, Node* t2) {
    if (t1 == NULL || t2 == NULL) return NULL;
    if (t1->type == 0 && t2->type == 0) {
        // both leaves
        Node* n = (Node*)malloc(sizeof(Node));
        n->type = 0;
        n->left = n->right = NULL;
        return n;
    }
    if (t1->type == 1 && t2->type == 1) {
        Node* left = intersect(t1->left, t2->left);
        Node* right = intersect(t1->right, t2->right);
        if (left == NULL && right == NULL) return NULL;
        Node* n = (Node*)malloc(sizeof(Node));
        n->type = 1;
        n->left = left;
        n->right = right;
        return n;
    }
    // one is leaf, other internal -> no common structure
    return NULL;
}

Node* union_trees(Node* t1, Node* t2) {
    if (t1 == NULL && t2 == NULL) return NULL;
    if (t1 == NULL) return t2;
    if (t2 == NULL) return t1;
    if (t1->type == 0 && t2->type == 0) {
        Node* n = (Node*)malloc(sizeof(Node));
        n->type = 0;
        n->left = n->right = NULL;
        return n;
    }
    if (t1->type == 0 && t2->type == 1) {
        Node* n = (Node*)malloc(sizeof(Node));
        n->type = 1;
        n->left = union_trees(t1, t2->left);
        n->right = union_trees(NULL, t2->right);
        return n;
    }
    if (t1->type == 1 && t2->type == 0) {
        Node* n = (Node*)malloc(sizeof(Node));
        n->type = 1;
        n->left = union_trees(t1->left, t2);
        n->right = union_trees(t1->right, NULL);
        return n;
    }
    // both internal
    Node* left = union_trees(t1->left, t2->left);
    Node* right = union_trees(t1->right, t2->right);
    Node* n = (Node*)malloc(sizeof(Node));
    n->type = 1;
    n->left = left;
    n->right = right;
    return n;
}

