typedef struct Node {
    struct Node *l, *r;
} Node;

static const char *p;

static void skip_spaces(void) {
    while (*p && isspace((unsigned char)*p)) p++;
}

static Node* new_node(Node *l, Node *r) {
    Node *x = (Node*)malloc(sizeof(Node));
    x->l = l;
    x->r = r;
    return x;
}

/* Grammar:
   tree := '0' | '(' tree tree ')'
   0 means empty tree
*/
static Node* parse_tree(void) {
    skip_spaces();
    if (*p == '0') {
        p++;
        return NULL;
    }
    if (*p == '(') {
        p++;
        Node *l = parse_tree();
        Node *r = parse_tree();
        skip_spaces();
        if (*p == ')') p++;
        return new_node(l, r);
    }
    return NULL;
}

static Node* tree_union(Node *a, Node *b) {
    if (!a && !b) return NULL;
    Node *l = tree_union(a ? a->l : NULL, b ? b->l : NULL);
    Node *r = tree_union(a ? a->r : NULL, b ? b->r : NULL);
    return new_node(l, r);
}

static Node* tree_intersection(Node *a, Node *b) {
    if (!a || !b) return NULL;
    Node *l = tree_intersection(a->l, b->l);
    Node *r = tree_intersection(a->r, b->r);
    return new_node(l, r);
}

static void print_tree(Node *t) {
    if (!t) {
        putchar('0');
        return;
    }
    putchar('(');
    print_tree(t->l);
    print_tree(t->r);
    putchar(')');
}

static void free_tree(Node *t) {
    if (!t) return;
    free_tree(t->l);
    free_tree(t->r);
    free(t);
}

int main(void) {
    char line[100000];

    while (fgets(line, sizeof(line), stdin)) {
        p = line;
        skip_spaces();
        if (!*p) continue;

        char op = *p++;
        Node *a = parse_tree();
        Node *b = parse_tree();
        Node *res = NULL;

        if (op == 'u')
            res = tree_union(a, b);
        else
            res = tree_intersection(a, b);

        print_tree(res);
        putchar('\n');

        free_tree(a);
        free_tree(b);
        free_tree(res);
    }

    return 0;
}

