            idx += 2;
            return null;
        }
        // '(' then value
        idx++; // skip '('
        Node node = new Node(s.charAt(idx));
        idx++; // skip value
        node.left = parseExpr(s);
        node.right = parseExpr(s);
        idx++; // skip ')'
        return node;
    }

    static Node intersect(Node t1, Node t2) {
        if (t1 == null || t2 == null) return null;
        Node node = new Node(t1.val);
        node.left = intersect(t1.left, t2.left);
        node.right = intersect(t1.right, t2.right);
        // If both children are null, keep node; if one is null, still keep node
        return node;
    }

    static Node union(Node t1, Node t2) {
        if (t1 == null && t2 == null) return null;
        if (t1 == null) return cloneTree(t2);
        if (t2 == null) return cloneTree(t1);
        Node node = new Node(t1.val);
        node.left = union(t1.left, t2.left);
        node.right = union(t1.right, t2.right);
        return node;
    }

    static Node cloneTree(Node t) {
        if (t == null) return null;
        Node node = new Node(t.val);
        node.left = cloneTree(t.left);
        node.right = cloneTree(t.right);
        return node;
    }

    static String serialize(Node t) {
        if (t == null) return "()";
        return "(" + t.val + serialize(t.left) + serialize(t.right) + ")";
