public class Main {
    static class Node {
        Node left, right;
        Node(Node l, Node r) { left = l; right = r; }
    }

    static class Parser {
        char[] s;
        int idx;

        Parser(String str, int start) {
            this.s = str.toCharArray();
            this.idx = start;
        }

        Node parseTree() {
            // tree := '(' tree tree ')' | '.'
            if (s[idx] == '.') {
                idx++;
                return null;
            }
            // '('
            idx++;
            Node left = parseTree();
            Node right = parseTree();
            // ')'
            idx++;
            return new Node(left, right);
        }
    }

    static Node union(Node a, Node b) {
        if (a == null && b == null) return null;
        Node left = union(a == null ? null : a.left, b == null ? null : b.left);
        Node right = union(a == null ? null : a.right, b == null ? null : b.right);
        return new Node(left, right);
    }

    static Node intersection(Node a, Node b) {
        if (a == null || b == null) return null;
        Node left = intersection(a.left, b.left);
        Node right = intersection(a.right, b.right);
        return new Node(left, right);
    }

    static void print(Node root, StringBuilder sb) {
        if (root == null) {
            sb.append('.');
            return;
        }
        sb.append('(');
        print(root.left, sb);
        print(root.right, sb);
        sb.append(')');
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            all.append(line.trim());
        }

        String input = all.toString();
        if (input.isEmpty()) return;

        int p = 0;
        char op = input.charAt(p++);
        Parser parser = new Parser(input, p);
        Node t1 = parser.parseTree();
        Node t2 = parser.parseTree();

        Node ans = (op == 'i') ? intersection(t1, t2) : union(t1, t2);

        StringBuilder out = new StringBuilder();
        print(ans, out);
        System.out.print(out.toString());
    }
}

