using namespace std;

struct Node {
    char val;
    shared_ptr<Node> left, right;
    Node(char v) : val(v), left(nullptr), right(nullptr) {}
};

// Parse a tree from a string starting at index i
// Returns the node and updates index
shared_ptr<Node> parse_tree(const string& s, size_t& i) {
    // skip spaces (shouldn't be any, but just in case)
    while (i < s.size() && isspace(s[i])) ++i;

    if (i >= s.size()) return nullptr;

    if (s[i] == '(') {
        // Empty node: ()
        if (i+1 < s.size() && s[i+1] == ')') {
            i += 2;
            return nullptr;
        }
        // Non-empty node: (val left right)
        ++i; // skip '('
        char val = s[i];
        ++i; // skip val
        auto left = parse_tree(s, i);
        auto right = parse_tree(s, i);
        // skip ')'
        if (i < s.size() && s[i] == ')') ++i;
        auto node = make_shared<Node>(val);
        node->left = left;
        node->right = right;
        return node;
    }
    return nullptr;
}

// Serialize tree to string
string serialize(shared_ptr<Node> root) {
    if (!root) return "()";
    string s = "(";
    s += root->val;
    s += serialize(root->left);
    s += serialize(root->right);
    s += ")";
    return s;
}

// Intersection: node exists in both trees
shared_ptr<Node> intersect(shared_ptr<Node> t1, shared_ptr<Node> t2) {
    if (!t1 || !t2) return nullptr;
    auto node = make_shared<Node>(t1->val);
    node->left = intersect(t1->left, t2->left);
    node->right = intersect(t1->right, t2->right);
    return node;
}

// Union: node exists in either tree (if both, take from t1)
shared_ptr<Node> union_trees(shared_ptr<Node> t1, shared_ptr<Node> t2) {
    if (!t1 && !t2) return nullptr;
    if (!t1) return t2;
    if (!t2) return t1;
    auto node = make_shared<Node>(t1->val);
    node->left = union_trees(t1->left, t2->left);
    node->right = union_trees(t1->right, t2->right);
    return node;
}

int main() {
