struct Node {
    bool exists = false;
    Node* left = nullptr;
    Node* right = nullptr;
};

Node* parseTree(const string& s, int& p) {
    // Tree format:
    // ()           -> empty tree
    // ( <left> <right> ) -> non-empty node
    if (p >= (int)s.size() || s[p] != '(') return nullptr;
    ++p; // skip '('
    if (p < (int)s.size() && s[p] == ')') {
        ++p; // skip ')'
        return nullptr;
    }
    Node* node = new Node();
    node->exists = true;
    node->left = parseTree(s, p);
    node->right = parseTree(s, p);
    if (p < (int)s.size() && s[p] == ')') ++p;
    return node;
}

Node* treeUnion(Node* a, Node* b) {
    if (!a && !b) return nullptr;
    Node* node = new Node();
    node->exists = true;
    node->left = treeUnion(a ? a->left : nullptr, b ? b->left : nullptr);
    node->right = treeUnion(a ? a->right : nullptr, b ? b->right : nullptr);
    return node;
}

Node* treeIntersection(Node* a, Node* b) {
    if (!a || !b) return nullptr;
    Node* node = new Node();
    node->exists = true;
    node->left = treeIntersection(a->left, b->left);
    node->right = treeIntersection(a->right, b->right);
    return node;
}

void printTree(Node* root, ostream& out) {
    if (!root) {
        out << "()";
        return;
    }
    out << '(';
    printTree(root->left, out);
    printTree(root->right, out);
    out << ')';
}

