    if t1 is None:
        return t2
    if t2 is None:
        return t1
    return (union(t1[0], t2[0]), union(t1[1], t2[1]))

import sys

sys.setrecursionlimit(10**7)

class Node:
    __slots__ = ("left", "right")
    def __init__(self, left=None, right=None):
        self.left = left
        self.right = right

def parse_tree(s, i):
    # Tree format:
    # ()              -> empty tree
    # ( <left> <right> ) -> non-empty node
    # with no spaces necessarily
    if s[i] != '(':
        raise ValueError("Expected '('")
    i += 1
    if s[i] == ')':
        return None, i + 1
    left, i = parse_tree(s, i)
    right, i = parse_tree(s, i)
    if s[i] != ')':
        raise ValueError("Expected ')'")
    return Node(left, right), i + 1

def intersect(a, b):
    if a is None or b is None:
        return None
    return Node(intersect(a.left, b.left), intersect(a.right, b.right))

def union(a, b):
    if a is None:
        return b
    if b is None:
        return a
    return Node(union(a.left, b.left), union(a.right, b.right))

def to_string(t):
    if t is None:
        return "()"
    return "(" + to_string(t.left) + to_string(t.right) + ")"

def main():
    data = sys.stdin.read()
    if not data:
        return

    # Keep only meaningful characters: operation letters and parentheses
    tokens = [c for c in data if c in 'iu()']
    n = len(tokens)
    i = 0
    out = []

    while i < n:
        op = tokens[i]
        i += 1
        t1, i = parse_tree(tokens, i)
        t2, i = parse_tree(tokens, i)

        if op == 'i':
            res = intersect(t1, t2)
        else:
            res = union(t1, t2)

        out.append(to_string(res))

    sys.stdout.write("\n".join(out))

